#include <print>
#include <numeric>
#include <vector>

int main() {
    std::vector<int> a = {1, 2, 3, 4, 5};
    std::vector<int> pre(a.size() + 1, 0);
    std::partial_sum(a.begin(), a.end(), pre.begin() + 1);
    for (size_t i = 0; i < pre.size(); ++i) std::print("pre[{}]={} ", i, pre[i]);
    std::println("");
    std::println("第 3~5 个：{} - {} = {}", pre[5], pre[2], pre[5] - pre[2]);
    // pre[i] 存的是前 i 个数加完的结果，第 0 格是 0 那个哨兵
    return 0;
}

